"use strict";(self.webpackChunkgrc=self.webpackChunkgrc||[]).push([[24881],{91593:e=>{e.exports=JSON.parse('{"title":"Acropolis: A Portable, AI-Driven Semantic Search System for HPC","authors":["R. Pawar","L. Logan","J. Cernuda","X.-H. Sun","A. Kougkas"],"venue":"The 22nd IEEE International Conference on eScience (eScience\'26)","type":"Conference","date":"September, 2026","month":9,"year":2026,"doi":"10.1109/eScience70237.2026.00045","tags":["AI","Semantic Search","HPC","MCP","Tiered Storage"],"links":{"pdf":"http://cs.iit.edu/~scs/assets/files/pawar2026acropolis.pdf","bibtex":"http://cs.iit.edu/~scs/assets/files/pawar2026acropolis.bib","citation":"http://cs.iit.edu/~scs/assets/files/pawar2026acropolis.txt"},"abstract":"LLM agents are now a primary interface to data repositories, but they locate files by issuing speculative regex queries through glob, grep, and file reads, creating a guess-and-check loop that is expensive in tool calls and tokens and ignores metadata embedded in scientific file formats. We present Acropolis, a semantic search system that augments a tiered filesystem with adaptive-depth content indexing and exposes it to agents through a typed natural-language interface. Acropolis provides a transparent file-summary operator in the I/O ingest path with content-addressable idempotency, a pluggable search-backend abstraction for lexical, vector, and graph engines, and an MCP server for compatible agents. On a 70-query CMIP6 retrieval benchmark, an agent using Acropolis matches the shell-tool baseline on retrieval accuracy while substantially reducing tool and backend calls per query and LLM token consumption.","slug":"pawar-2026-acropolis-1f2a"}')}}]);